// Package registry holds the enforcement tables that every process of sluis compiles in: the store's rules
// (actor x kind x verb), key's rules (actor x purpose x op), the call graph and the pinned uids.
//
// The tables in zz_registry.go are generated by tools/gen/registry from docs/architecture/actors.yaml,
// kinds.yaml and keys.yaml, so that nothing that enforces least privilege is written by hand (ADR 0002,
// "Registries generate the enforcement"). Run `just registry-gen` after a registry changes; `just
// registry-check` fails while the generated files are stale. This file is the hand-written API over them.
// The Rust crate kits/rust/sluis-registry has the same API and the same data.
//
// Every lookup is by exact name: an unknown actor, kind, purpose or verb is denied, never an error.
package registry

import (
	"slices"
	"time"
)

// Kind is a row of the kind registry (docs/architecture/kinds.yaml).
type Kind struct {
	Name, Segment, Class, Scope, Treatment, Writer string // Class: config|secret|durable|temp; Scope: boundary|boundary+tenant
	SelfScoped, Personal, Exportable, BackedUp     bool
	Watched                                        bool // some actor may watch the kind
	// TTLDefault and TTLMax are the lifetime of a temp kind, and of a durable kind that carries an expiry. A default
	// of 0 means "the writer must give a TTL"; the store enforces that.
	TTLDefault, TTLMax time.Duration
	Indexes            []string
}

// Actor is a row of the actor registry (docs/architecture/actors.yaml), or a platform piece (Family "platform").
type Actor struct {
	Name, Family, Language string
	Holder                 bool
	Ports, Calls, Egress   []string
}

// The bit of each verb in a store rule: bit i is verbNames[i]; bit selfShift+i marks the verb as self-scoped.
var verbNames = [...]string{"get", "list", "create", "update", "delete", "apply", "watch"}

const selfShift = 7

var opNames = [...]string{"seal", "open", "sign", "mac", "public-key", "wrap", "unwrap"}

func (k Kind) clone() Kind {
	k.Indexes = slices.Clone(k.Indexes)
	return k
}

// KindByName returns the kind with a PascalCase name such as "DataKeyWrap".
func KindByName(name string) (Kind, bool) {
	i, ok := kindByName[name]
	if !ok {
		return Kind{}, false
	}
	return kinds[i].clone(), true
}

// KindBySegment returns the kind with an address segment such as "data-key-wrap".
func KindBySegment(seg string) (Kind, bool) {
	i, ok := kindBySegment[seg]
	if !ok {
		return Kind{}, false
	}
	return kinds[i].clone(), true
}

// Kinds returns every kind, in the order of the registry.
func Kinds() []Kind {
	out := make([]Kind, len(kinds))
	for i, k := range kinds {
		out[i] = k.clone()
	}
	return out
}

func storeRule(actor, segment string) (uint16, bool) {
	bits, ok := storeRules[actor][segment]
	return bits, ok
}

func verbBit(verb string) (uint, bool) {
	for i, v := range verbNames {
		if v == verb {
			return uint(i), true
		}
	}
	return 0, false
}

// StoreAllows says whether the actor may use the verb (get, list, create, update, delete, apply or watch) on
// the kind with the address segment. Everything the registries do not allow is denied.
func StoreAllows(actor, segment, verb string) bool {
	bits, ok := storeRule(actor, segment)
	if !ok {
		return false
	}
	i, ok := verbBit(verb)
	return ok && bits&(1<<i) != 0
}

// StoreSelfScoped says whether any rule of the actor on the kind holds only for ids that start with
// "<actor>/". It is the strict answer: use StoreSelfScopedFor when the verb is known, because an actor may be
// bound to its own ids when it writes and free to read the ids of others (an adapter and its facts).
func StoreSelfScoped(actor, segment string) bool {
	bits, ok := storeRule(actor, segment)
	return ok && bits>>selfShift != 0
}

// StoreSelfScopedFor says whether the actor's rule for this verb on the kind holds only for ids that start
// with "<actor>/". It is false when the actor may not use the verb at all.
func StoreSelfScopedFor(actor, segment, verb string) bool {
	bits, ok := storeRule(actor, segment)
	if !ok {
		return false
	}
	i, ok := verbBit(verb)
	return ok && bits&(1<<i) != 0 && bits&(1<<(selfShift+i)) != 0
}

// IsWriter says whether the actor may write the kind (create, update, delete or apply). A self-scoped kind has
// every actor as a writer, each under its own ids.
func IsWriter(actor, segment string) bool {
	bits, ok := storeRule(actor, segment)
	return ok && bits&(1<<2) != 0 // create
}

// KeyAllows says whether the actor may ask key for the op (seal, open, sign, mac, public-key, wrap or unwrap)
// under the key purpose.
func KeyAllows(actor, purpose, op string) bool {
	ops, ok := keyRules[actor][purpose]
	if !ok {
		return false
	}
	i := slices.Index(opNames[:], op)
	return i >= 0 && ops&(1<<i) != 0
}

// MayCall says whether the caller may call the callee over its transport. The audit transport (the spool) is
// the callee "transport". A holder reaches its own drivers outside this graph: a driver checks DriverOwner.
func MayCall(caller, callee string) bool {
	_, ok := slices.BinarySearch(callees[caller], callee)
	return ok
}

// CallersOf returns the sorted callers of a callee, for socket groups and units.
func CallersOf(callee string) []string {
	return slices.Clone(callers[callee])
}

// UID returns the uid of the named actor, platform piece, driver user or harness user in the boundary with the
// uid block: 61000 + ordinal + 1000 x uidBlock (REQ-ISO-072). The ordinal is the name's place in
// tools/gen/registry/uids.yaml. It is false for an unknown name or a block that gives no valid uid.
func UID(name string, uidBlock uint32) (uint32, bool) {
	ord := slices.Index(uidNames, name)
	if ord < 0 {
		return 0, false
	}
	uid := uint64(uidBase) + uint64(ord) + uint64(uidBlockStride)*uint64(uidBlock)
	if uid > 1<<32-3 { // 2^32-1 is "no uid" and 2^32-2 is the overflow uid
		return 0, false
	}
	return uint32(uid), true
}

// NameForUID is the reverse of UID.
func NameForUID(uid uint32) (name string, uidBlock uint32, ok bool) {
	if uid < uidBase {
		return "", 0, false
	}
	rel := uid - uidBase
	ord := int(rel % uidBlockStride)
	if ord >= len(uidNames) {
		return "", 0, false
	}
	return uidNames[ord], rel / uidBlockStride, true
}

// DriverOwner returns the actor that owns a driver, from the driver's user name: "driver-store-rqlite" is
// owned by "store".
func DriverOwner(driver string) (owner string, ok bool) {
	owner, ok = driverOwners[driver]
	return owner, ok
}

func (a Actor) clone() Actor {
	a.Ports = slices.Clone(a.Ports)
	a.Calls = slices.Clone(a.Calls)
	a.Egress = slices.Clone(a.Egress)
	return a
}

// ActorByName returns an actor of the registry or a platform piece such as "sluis-node".
func ActorByName(name string) (Actor, bool) {
	i, ok := actorIndex[name]
	if !ok {
		return Actor{}, false
	}
	return actors[i].clone(), true
}

// Actors returns the actors in the order of the registry, then the platform pieces (Family "platform").
func Actors() []Actor {
	out := make([]Actor, len(actors))
	for i, a := range actors {
		out[i] = a.clone()
	}
	return out
}
